const GWH = R.ertragJahr1 / 1e6;
const BB_JAHR = BB_EUR_PRO_MW * MWP;
const MV_JAHR = (MV_GEMEINDE_EUR_PRO_MW + MV_EINWOHNER_EUR_PRO_MW) * MWP;
const rund = (n, s = 1000) => fmtEur(Math.round(n / s) * s);

