// node check_art.mjs <slug> : Status, Überlauf, Lesezeit, Fehler, Ausschnitte bei 390 px
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const [slug] = process.argv.slice(2);
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 390, height: 844 } });
const fehler = [];
p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 200)));
const r = await p.goto("http://localhost:3100/ratgeber/" + slug, { waitUntil: "load", timeout: 180000 });
await p.waitForTimeout(1500);
try { await p.getByRole("button", { name: "Nur notwendige" }).click({ timeout: 1500 }); } catch {}
const info = await p.evaluate(() => {
  document.querySelectorAll(".ov-reveal").forEach((e) => e.classList.add("is-visible"));
  const sw = document.documentElement.scrollWidth, cw = document.documentElement.clientWidth;
  const breit = [...document.querySelectorAll("body *")].filter((e) => { const r = e.getBoundingClientRect(); return r.right > cw + 1 && getComputedStyle(e).position !== "fixed"; })
    .filter((e) => !e.closest("[class*=overflow-x]")).slice(0, 8).map((e) => e.tagName + "." + (e.className || "").toString().slice(0, 60));
  const lese = (document.body.innerText.match(/\d+\s*Min\. Lesezeit/) || [""])[0];
  return { sw, cw, breit, lese, tabellen: document.querySelectorAll("table").length, h: document.body.scrollHeight };
});
console.log(r.status(), JSON.stringify(info), fehler.join("\n"));
const tabs = await p.$$("table");
let i = 0;
for (const t of tabs.slice(0, 4)) { await t.scrollIntoViewIfNeeded(); await p.waitForTimeout(300); await p.screenshot({ path: fileURLToPath(new URL(`./shots/${slug}_tab${i++}.png`, import.meta.url)) }); }
await b.close();

